CREATE TABLE semio_graph_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_graph_node (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_graph_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL, position_x REAL, position_y REAL, position_x_ieee754_bits INTEGER, position_x_numeric_class TEXT, position_y_ieee754_bits INTEGER, position_y_numeric_class TEXT);
CREATE TABLE semio_graph_port (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES semio_graph_node(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('in','out','in_out')));
CREATE TABLE semio_graph_property (id INTEGER PRIMARY KEY, node_id INTEGER NOT NULL REFERENCES semio_graph_node(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), property_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES semio_graph_value(id));
CREATE TABLE semio_graph_edge (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_graph_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, source_node_id INTEGER NOT NULL REFERENCES semio_graph_node(id), target_node_id INTEGER NOT NULL REFERENCES semio_graph_node(id), kind TEXT NOT NULL, label TEXT NOT NULL);
CREATE TABLE semio_graph_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('null','bool','int','float','str','bytes','list','map','ref')), boolean_value INTEGER CHECK (boolean_value IN (0,1)), integer_lexeme TEXT, float_lexeme TEXT, string_value TEXT, bytes_value BLOB, reference_native_id TEXT);
CREATE TABLE semio_graph_list_element (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES semio_graph_value(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), value_id INTEGER NOT NULL REFERENCES semio_graph_value(id));
CREATE TABLE semio_graph_map_entry (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES semio_graph_value(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), member_key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES semio_graph_value(id));
